.hz__mapwrap {
  position: relative;
  min-height: 420px;
  border: 1px solid var(--zh-color-border);
  background: #f4f6f8;
}

.hz__canvas {
  display: block;
  touch-action: none;
  cursor: grab;
}

.hz__canvas:focus-visible {
  outline: 3px solid var(--zh-color-focus);
  outline-offset: 2px;
}

.hz__canvas:active {
  cursor: grabbing;
}

.hz__controls {
  position: absolute;
  top: 8px;
  left: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
  padding: 4px;
  background: rgb(255 255 255 / 92%);
  border: 1px solid var(--zh-color-border);
  box-shadow: var(--zh-shadow-card);
}

.hz__toggle {
  display: inline-flex;
  gap: 6px;
  align-items: center;
  padding: 0 6px;
  font-size: var(--zh-font-small);
}

.hz__hover {
  position: absolute;
  margin: 0;
  padding: 2px 8px;
  max-width: 480px;
  border-color: var(--zh-color-danger);
}

/* --- timeline ------------------------------------------------------- */

.hz__timeline {
  margin-top: 12px;
  padding: 12px;
  background: var(--zh-color-surface);
  border: 1px solid var(--zh-color-border);
}

.hz__timeline-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.hz__timeline-row--form {
  margin-top: 8px;
  justify-content: space-between;
}

.hz__range {
  width: 100%;
  margin: 10px 0 4px;
  accent-color: var(--zh-color-accent);
}

.hz__range:focus-visible {
  outline: 3px solid var(--zh-color-focus);
  outline-offset: 4px;
}

.hz__yearform {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.hz__year {
  width: 9.5rem;
}

.hz__yearlabel {
  font-weight: 600;
}

.hz__yearhint {
  flex-basis: 100%;
  margin: 0;
  font-size: var(--zh-font-tiny);
  color: var(--zh-color-text-soft);
}

.hz__note {
  margin: 0;
  flex: 1 1 260px;
  font-size: var(--zh-font-small);
  color: var(--zh-color-text-soft);
}

/* --- details panel -------------------------------------------------- */

.hz__panel {
  padding: 12px;
  background: var(--zh-color-surface);
  border: 1px solid var(--zh-color-border);
