import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const PORT = 9334;
const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars',
  `--remote-debugging-port=${PORT}`, '--window-size=1440,1200', 'about:blank',
], { stdio: ['ignore', 'ignore', 'ignore'] });

async function getWs() {
  for (let i = 0; i < 50; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
      const page = list.find((t) => t.type === 'page');
      if (page) return page.webSocketDebuggerUrl;
    } catch {}
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error('no chrome');
}
class CDP {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map(); this.handlers = new Map();
    ws.addEventListener('message', (ev) => {
      const m = JSON.parse(ev.data);
      if (m.id && this.pending.has(m.id)) { const p = this.pending.get(m.id); this.pending.delete(m.id); m.error ? p.reject(new Error(m.error.message)) : p.resolve(m.result); return; }
      for (const h of this.handlers.get(m.method) ?? []) h(m.params);
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => { if (this.pending.delete(id)) reject(new Error(method + ' timed out')); }, 30000);
    });
  }
  on(method, fn) { if (!this.handlers.has(method)) this.handlers.set(method, []); this.handlers.get(method).push(fn); }
  async eval(expression) {
    const r = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.text + ' ' + JSON.stringify(r.exceptionDetails.exception?.description ?? ''));
    return r.result.value;
  }
  async waitFor(expression, timeout = 10000) {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const v = await this.eval(expression);
      if (v) return v;
      await new Promise((r) => setTimeout(r, 100));
    }
    throw new Error('waitFor timeout: ' + expression);
  }
}

const ws = new WebSocket(await getWs());
await new Promise((r) => ws.addEventListener('open', r, { once: true }));
const cdp = new CDP(ws);
const logs = [];
cdp.on('Runtime.consoleAPICalled', (p) => { if (p.type !== 'info') logs.push({ type: p.type, args: p.args.map((a) => a.value ?? a.description) }); });
cdp.on('Runtime.exceptionThrown', (p) => logs.push({ type: 'exception', desc: p.exceptionDetails.exception?.description ?? p.exceptionDetails.text }));
const netfail = [];
cdp.on('Network.loadingFailed', (p) => netfail.push({ id: p.requestId, error: p.errorText, type: p.type }));
cdp.on('Network.requestWillBeSent', (p) => { const f = netfail.find((n) => n.id === p.requestId); if (f) f.url = p.request.url; });
cdp.on('Network.responseReceived', (p) => { const f = netfail.find((n) => n.id === p.requestId); if (f) f.status = p.response.status; });
await cdp.send('Runtime.enable');
await cdp.send('Network.enable');
await cdp.send('Page.enable');
await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1200, deviceScaleFactor: 1, mobile: false });

async function nav(url) {
  await cdp.send('Page.navigate', { url });
  await cdp.waitFor(`document.querySelector('#hz-status')?.textContent?.match(/drawn|Could not/)`);
  await new Promise((r) => setTimeout(r, 600));
}
async function snap(name, expr) {
  await new Promise((r) => setTimeout(r, 300));
  const v = await cdp.eval(expr);
  console.log(name, JSON.stringify(v));
  return v;
}

await nav('http://127.0.0.1:8787/?view=history&year=1500');
await snap('initial', `(() => ({
  url: location.search,
  heading: document.querySelector('#hz-heading')?.textContent,
  status: document.querySelector('#hz-status')?.textContent,
  note: document.querySelector('#hz-note')?.textContent,
  canvasLabel: document.querySelector('#hz-canvas')?.getAttribute('aria-label'),
  rangeValue: document.querySelector('#hz-range')?.value,
  rangeMax: document.querySelector('#hz-range')?.max,
  rangeText: document.querySelector('#hz-range')?.getAttribute('aria-valuetext'),
  yearField: document.querySelector('#hz-year-input')?.value,
  polities: document.querySelectorAll('#hz-polity option').length,
  selected: document.querySelector('#hz-polity')?.value,
  detailsHidden: document.querySelector('#hz-details')?.hidden,
  mapHeight: document.querySelector('#hz-canvas')?.getBoundingClientRect().height,
  mapWidth: document.querySelector('#hz-canvas')?.getBoundingClientRect().width,
  modeLinks: [...document.querySelectorAll('.app-mode-switch')].map(a => ({ text: a.textContent, hidden: a.hidden, current: a.getAttribute('aria-current') })),
  heroLink: document.querySelector('.app-history-link')?.getAttribute('href'),
}))()`);

// year change via the labelled text field + submit
await cdp.eval(`(() => { const i = document.querySelector('#hz-year-input'); i.value = '1900'; i.form.requestSubmit(); return true; })()`);
await cdp.waitFor(`document.querySelector('#hz-canvas')?.getAttribute('aria-label')?.includes('1900')`);
await snap('after 1900', `(() => ({
  url: location.search,
  status: document.querySelector('#hz-status')?.textContent,
  note: document.querySelector('#hz-note')?.textContent,
  rangeValue: document.querySelector('#hz-range')?.value,
  yearField: document.querySelector('#hz-year-input')?.value,
  polities: document.querySelectorAll('#hz-polity option').length,
  canvasLabel: document.querySelector('#hz-canvas')?.getAttribute('aria-label'),
  politiesInYear: [...document.querySelectorAll('#hz-polity option')].map(o => o.textContent).filter(t => /German Empire|Ottoman|USSR/.test(t)),
}))()`);

// dropdown jump to a polity opens the details panel
const optionValue = await cdp.eval(`(() => { const o = [...document.querySelectorAll('#hz-polity option')].find(o => o.textContent === 'German Empire'); return o?.value ?? ''; })()`);
console.log('german empire option', optionValue);
await cdp.eval(`(() => { const s = document.querySelector('#hz-polity'); s.value = ${JSON.stringify(optionValue)}; s.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`);
await new Promise((r) => setTimeout(r, 400));
await snap('details', `(() => ({
  hidden: document.querySelector('#hz-details')?.hidden,
  title: document.querySelector('#hz-details-title')?.textContent,
  facts: [...document.querySelectorAll('#hz-details .hz__facts dt')].map((dt, i) => dt.textContent + ': ' + document.querySelectorAll('#hz-details .hz__facts dd')[i]?.textContent),
  source: document.querySelector('#hz-details .hz__source-line')?.textContent,
  sourceLink: document.querySelector('#hz-details .hz__source-line a')?.href,
  url: location.search,
}))()`);
await cdp.send('Page.captureScreenshot', {}).then((r) => writeFileSync('/tmp/history-1900-details.png', Buffer.from(r.data, 'base64')));

// close details
await cdp.eval(`document.querySelector('[data-hz="close-details"]').click()`);
await new Promise((r) => setTimeout(r, 200));

// BCE
await cdp.eval(`(() => { const i = document.querySelector('#hz-year-input'); i.value = '1000 BCE'; i.form.requestSubmit(); return true; })()`);
await cdp.waitFor(`document.querySelector('#hz-canvas')?.getAttribute('aria-label')?.includes('1000 BCE')`);
await snap('bce', `({
  url: location.search,
  note: document.querySelector('#hz-note')?.textContent,
  yearField: document.querySelector('#hz-year-input')?.value,
  polities: document.querySelectorAll('#hz-polity option').length,
  canvasLabel: document.querySelector('#hz-canvas')?.getAttribute('aria-label'),
  status: document.querySelector('#hz-status')?.textContent,
})`);

// nearest snapshot honesty: 1899
await cdp.eval(`(() => { const i = document.querySelector('#hz-year-input'); i.value = '1899'; i.form.requestSubmit(); return true; })()`);
await cdp.waitFor(`document.querySelector('#hz-note')?.textContent?.includes('1900')`);
await snap('nearest', `({
  note: document.querySelector('#hz-note')?.textContent,
  canvasLabel: document.querySelector('#hz-canvas')?.getAttribute('aria-label'),
  url: location.search,
})`);

// deep link restore 1914 + hv
await nav('http://127.0.0.1:8787/?view=history&year=1914&hv=40.000,15.000,4.00');
await snap('deep link', `({
  note: document.querySelector('#hz-note')?.textContent,
  url: location.search,
  rangeText: document.querySelector('#hz-range')?.getAttribute('aria-valuetext'),
  yearField: document.querySelector('#hz-year-input')?.value,
  canvasLabel: document.querySelector('#hz-canvas')?.getAttribute('aria-label'),
})`);

// keyboard pan/zoom changes hv
await cdp.eval(`document.querySelector('#hz-canvas').focus()`);
const beforeKey = await cdp.eval(`location.search`);
await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key: '+', code: 'Equal', text: '+' });
await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: '+', code: 'Equal' });
await new Promise((r) => setTimeout(r, 700));
await snap('keyboard zoom', `({ before: ${JSON.stringify(beforeKey)}, after: location.search, focused: document.activeElement?.id })`);

// polity search
await cdp.eval(`(() => { const i = document.querySelector('#hz-search'); i.value = 'Prussia'; i.dispatchEvent(new Event('input', { bubbles: true })); return true; })()`);
await cdp.waitFor(`document.querySelectorAll('#hz-search-results li').length > 0`);
await snap('polity search', `({
  hint: document.querySelector('#hz-search-hint')?.textContent,
  results: [...document.querySelectorAll('#hz-search-results button')].slice(0, 4).map(b => b.textContent),
})`);
await cdp.eval(`document.querySelector('#hz-search-results button').click()`);
await new Promise((r) => setTimeout(r, 900));
await snap('polity jump', `({
  url: location.search,
  note: document.querySelector('#hz-note')?.textContent,
  yearField: document.querySelector('#hz-year-input')?.value,
  details: document.querySelector('#hz-details')?.hidden,
  title: document.querySelector('#hz-details-title')?.textContent,
  searchValue: document.querySelector('#hz-search')?.value,
})`);

// timeline next / prev
const beforeNext = await cdp.eval(`location.search`);
await cdp.eval(`document.querySelector('[data-hz="next"]').click()`);
await new Promise((r) => setTimeout(r, 900));
await snap('next', `({ before: ${JSON.stringify(beforeNext)}, after: location.search, field: document.querySelector('#hz-year-input')?.value, disabled: document.querySelector('[data-hz="next"]')?.disabled })`);

// mobile
await cdp.send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
await nav('http://127.0.0.1:8787/?view=history&year=1600');
await snap('mobile', `(() => ({
  overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
  map: (() => { const r = document.querySelector('#hz-canvas')?.getBoundingClientRect(); return r ? { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) } : null; })(),
  heading: document.querySelector('#hz-heading')?.getBoundingClientRect().top,
  status: document.querySelector('#hz-status')?.textContent,
  headerLink: [...document.querySelectorAll('.app-mode-switch')].filter(a => !a.hidden).map(a => a.textContent),
}))()`);
await cdp.send('Page.captureScreenshot', {}).then((r) => writeFileSync('/tmp/history-mobile.png', Buffer.from(r.data, 'base64')));

console.log('LOGS', JSON.stringify(logs, null, 2));
console.log('NETFAIL', JSON.stringify(netfail, null, 2));
ws.close();
chrome.kill();

