class CDP { constructor(ws){this.ws=ws;this.id=0;this.pending=new Map();this.handlers=new Map();ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id&&this.pending.has(m.id)){const p=this.pending.get(m.id);this.pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result);return;}for(const h of this.handlers.get(m.method)??[])h(m.params);});}
 send(method,params={}){const id=++this.id;return new Promise((res,rej)=>{this.pending.set(id,{resolve:res,reject:rej});this.ws.send(JSON.stringify({id,method,params}));setTimeout(()=>{if(this.pending.delete(id))rej(new Error(method+' timed out'));},30000);});}
 on(m,f){if(!this.handlers.has(m))this.handlers.set(m,[]);this.handlers.get(m).push(f);}
