import { spawn } from 'node:child_process';
const PORT = 9336;
const chrome = spawn('chromium', ['--headless=new','--no-sandbox','--disable-gpu',`--remote-debugging-port=${PORT}`,'--window-size=1440,1200','about:blank'], { stdio: ['ignore','ignore','ignore'] });
async function getWs(){for(let i=0;i<50;i++){try{const l=await(await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();const p=l.find(t=>t.type==='page');if(p)return p.webSocketDebuggerUrl;}catch{}await new Promise(r=>setTimeout(r,200));}throw new Error('x');}
class CDP{constructor(ws){this.ws=ws;this.id=0;this.p=new Map();this.h=new Map();ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id&&this.p.has(m.id)){const q=this.p.get(m.id);this.p.delete(m.id);m.error?q.reject(new Error(m.error.message)):q.resolve(m.result);return;}for(const f of this.h.get(m.method)??[])f(m.params);});}send(method,params={}){const id=++this.id;return new Promise((res,rej)=>{this.p.set(id,{resolve:res,reject:rej});this.ws.send(JSON.stringify({id,method,params}));setTimeout(()=>{if(this.p.delete(id))rej(new Error(method+' timeout'));},30000);});}on(m,f){if(!this.h.has(m))this.h.set(m,[]);this.h.get(m).push(f);}async eval(expression){const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.text+' '+JSON.stringify(r.exceptionDetails.exception?.description??''));return r.result.value;}async waitFor(e,t=10000){const s=Date.now();while(Date.now()-s<t){const v=await this.eval(e);if(v)return v;await new Promise(r=>setTimeout(r,100));}throw new Error('timeout');}}
const ws=new WebSocket(await getWs());await new Promise(r=>ws.addEventListener('open',r,{once:true}));
const cdp=new CDP(ws);await cdp.send('Runtime.enable');await cdp.send('Page.enable');
await cdp.send('Page.navigate',{url:'http://127.0.0.1:8787/?view=history&year=1920'});
