const idx = await cdp.eval(`(()=>{const o=[...document.querySelectorAll('#hz-polity option')].find(o=>o.textContent==='East Prussia');return o?.value??'';})()`);
await cdp.eval(`(()=>{const s=document.querySelector('#hz-polity'); s.value=${JSON.stringify(idx)}; s.dispatchEvent(new Event('change',{bubbles:true})); return true;})()`);
for (let i=0;i<8;i++){ await new Promise(r=>setTimeout(r,300)); console.log(i, await cdp.eval(`({hidden:document.querySelector('#hz-details').hidden, title:document.querySelector('#hz-details-title').textContent, log:window.__log.length})`)); }
console.log('log', JSON.stringify(await cdp.eval(`window.__log`)));
