);

// Shareable state: year + map window, and the keyboard must move that window.
await cdp.send('Page.navigate', { url: `${BASE_URL}/?view=history&year=1914&hv=40.000,15.000,4.00` });
await cdp.waitFor(`document.querySelector('#hz-status')?.textContent?.includes('drawn') && document.querySelector('#hz-canvas')?.getAttribute('aria-label')?.includes('1914')`, { label: 'shared history link' });
await sleep(500);
const historyShared = await cdp.eval(`({
  url: location.search,
  note: document.querySelector('#hz-note').textContent,
  yearField: document.querySelector('#hz-year-input').value,
  rangeText: document.querySelector('#hz-range').getAttribute('aria-valuetext'),
})`);
await cdp.eval(`document.querySelector('#hz-canvas').focus()`);
await cdp.pressKey('+', { native: false, keyCode: 187, code: 'Equal' });
await cdp.waitFor(`location.search.includes('hv=40.000%2C15.000%2C4.50') || location.search.includes('hv=40.000,15.000,4.50')`, { label: 'keyboard zoom writes hv' });
const historyKeyboard = await cdp.eval(`({
  focused: document.activeElement?.id || '',
  hv: new URLSearchParams(location.search).get('hv'),
})`);
check(
  'History: a shared year + window link reopens exactly, and +/- zoom the focused map into it',
  historyShared.note.includes('Snapshot 1914 CE') &&
    historyShared.yearField === '1914 CE' &&
    /1914 CE/.test(historyShared.rangeText) &&
    historyKeyboard.focused === 'hz-canvas' &&
    historyKeyboard.hv === '40.000,15.000,4.50',
  JSON.stringify({ shared: historyShared, keyboard: historyKeyboard }),
);

// The details panel: clickable polity facts with the upstream source link.
const germanEmpireValue = await cdp.eval(`(() => [...document.querySelectorAll('#hz-polity option')].find((o) => o.textContent === 'German Empire')?.value ?? '')()`);
await cdp.eval(`(() => { const select = document.querySelector('#hz-polity'); select.value = ${JSON.stringify(germanEmpireValue)}; select.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`);
await cdp.waitFor(`document.querySelector('#hz-details') && !document.querySelector('#hz-details').hidden && document.querySelector('#hz-details-title')?.textContent === 'German Empire'`, { label: 'polity details' });
const historyDetails = await cdp.eval(`({
  title: document.querySelector('#hz-details-title').textContent,
  facts: [...document.querySelectorAll('#hz-details .hz__facts dt')].map((dt, i) => dt.textContent + ': ' + document.querySelectorAll('#hz-details .hz__facts dd')[i]?.textContent),
  source: document.querySelector('#hz-details .hz__source-line').textContent,
  sourceLink: document.querySelector('#hz-details .hz__source-line a')?.getAttribute('href') || '',
