})`);
check(
  'History: a polity opens clickable details naming the snapshot, precision and primary source',
  historyDetails.title === 'German Empire' &&
    historyDetails.facts.some((fact) => /Border precision/.test(fact)) &&
    historyDetails.facts.some((fact) => /Drawn snapshot: 1914 CE/.test(fact)) &&
    historyDetails.licence &&
    /^https:\/\/github\.com\/aourednik\/historical-basemaps/.test(historyDetails.sourceLink),
  JSON.stringify(historyDetails).slice(0, 300),
);
await cdp.screenshot(path.join(OUT_DIR, '14d-history-details.png')).then(() => report.screenshots.push('14d-history-details.png'));
