// Phone: the history view must fit, keep its controls reachable and keep a
// way back to the archive maps in the header.
await cdp.send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true, screenWidth: 390, screenHeight: 844 });
await cdp.send('Page.navigate', { url: `${BASE_URL}/?view=history&year=1600` });
await cdp.waitFor(`document.querySelector('#hz-status')?.textContent?.includes('drawn')`, { label: 'mobile history view' });
await sleep(600);
const historyMobile = await cdp.eval(`(() => {
  const canvas = document.querySelector('#hz-canvas').getBoundingClientRect();
  const controls = document.querySelector('.hz__controls').getBoundingClientRect();
  return {
    overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    canvas: { width: Math.round(canvas.width), height: Math.round(canvas.height) },
    controlsInside: controls.left >= -1 && controls.right <= window.innerWidth + 1,
    timelineVisible: document.querySelector('.hz__timeline').getBoundingClientRect().height > 100,
    backToMaps: [...document.querySelectorAll('.app-mode-switch')].filter((a) => !a.hidden).map((a) => a.textContent.trim()),
    heading: document.querySelector('#hz-heading').textContent,
  };
})()`);
check(
  'History at 390 px: no overflow, real map area, reachable controls and a link back to the archive',
  historyMobile.overflow <= 1 &&
    historyMobile.canvas.width > 300 &&
    historyMobile.canvas.height > 300 &&
    historyMobile.controlsInside &&
    historyMobile.timelineVisible &&
    historyMobile.backToMaps.includes('Maps'),
  JSON.stringify(historyMobile),
);
await cdp.screenshot(path.join(OUT_DIR, '14e-history-mobile.png')).then(() => report.screenshots.push('14e-history-mobile.png'));

// An unreachable snapshot degrades with a plain sentence and can be retried.
await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 960, deviceScaleFactor: 1, mobile: false });
await cdp.send('Network.setBlockedURLs', { urls: ['*/data/history/world_1960.json'] });
await cdp.send('Page.navigate', { url: `${BASE_URL}/?view=history&year=1960` });
let historyOutage = null;
try {
  historyOutage = await cdp.waitFor(
    `(() => {
      const error = document.querySelector('#hz-error');
      if (!error || error.hidden) return '';
      const text = error.textContent.replace(/\\s+/g, ' ').trim();
      return { text, status: document.querySelector('#hz-status').textContent, loadingHidden: document.querySelector('#hz-loading').hidden };
    })()`,
    { label: 'history snapshot outage', timeout: 20_000 },
  );
} catch {
  /* reported below */
}
check(
  'History: an unreachable snapshot says so in plain words and keeps the raw error out of the UI',
  Boolean(historyOutage) &&
    /1960 CE snapshot could not be loaded/.test(historyOutage.text) &&
    /Could not load 1960 CE/.test(historyOutage.status) &&
    historyOutage.loadingHidden === true &&
    !/Failed to fetch|TypeError|HTTP \\d{3}|undefined/.test(historyOutage.text),
  JSON.stringify(historyOutage),
);
await cdp.send('Network.setBlockedURLs', { urls: [] });
await cdp.click('[data-hz="retry"]');
await cdp.waitFor(`document.querySelector('#hz-status')?.textContent?.includes('drawn') && document.querySelector('#hz-note')?.textContent?.includes('1960')`, { label: 'history retry' });
const historyRetry = await cdp.eval(`({ status: document.querySelector('#hz-status').textContent, errorHidden: document.querySelector('#hz-error').hidden })`);
check(
  'History: “Try again” recovers the snapshot without a reload',
  /drawn/.test(historyRetry.status) && historyRetry.errorHidden === true,
  JSON.stringify(historyRetry),
);

