/**
 * Regression guards for the History / Borders view's DOM layer.
 *
 * The view is created entirely from JavaScript, so two defects that `node --test`
 * cannot see in a browser are worth pinning here:
 *
 *  - `dom.el` originally took exactly one children argument. `history.js` calls
 *    it with several children (the lead, status, controls, timeline forms), and
 *    every extra argument was silently dropped, which left half of the view's
 *    controls out of the DOM. The helper is variadic now and flattens one level,
 *    so both call styles work.
 *  - `drawFeature` passed an SVG path string to `CanvasRenderingContext2D.fill()`,
 *    which Chromium treats as the fill-rule enum and throws on — the canvas
 *    stayed blank with “Preparing … ” in the status line. The regression guard
 *    keeps the Path2D construction in place.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const historySource = await readFile(fileURLToPath(new URL('../public/app/history.js', import.meta.url)), 'utf8');

test('dom.el appends every child in both the variadic and the array form', async () => {
  const textNode = (text) => new TextNode(text);
  class Node {}
  class TextNode extends Node {
    constructor(text) {
      super();
      this.textContent = text;
    }
  }
  class Element extends Node {
    constructor(tag) {
      super();
      this.tagName = tag;
      this.children = [];
      this.attributes = {};
      this.dataset = {};
    }
    append(...children) {
      this.children.push(...children);
    }
    setAttribute(name, value) {
      this.attributes[name] = value;
    }
    addEventListener() {}
  }
  globalThis.Node = Node;
  globalThis.document = {
    createElement: (tag) => new Element(tag),
    createTextNode: (text) => textNode(text),
  };
  try {
    const { el } = await import(`../public/app/dom.js?dom-el=${Date.now()}`);
    const variadic = el('header', {}, el('h2', {}, 'Title'), el('p', {}, 'Lead'), 'tail');
    assert.equal(variadic.children.length, 3, 'three children survive');
    assert.equal(variadic.children[0].tagName, 'h2');
    assert.equal(variadic.children[1].tagName, 'p');
    assert.equal(variadic.children[2].textContent, 'tail');

    const arrayForm = el('ul', {}, [el('li', {}, 'a'), el('li', {}, 'b')]);
    assert.equal(arrayForm.children.length, 2, 'the documented array form still works');

    const ignored = el('div', {}, el('span', {}, 'kept'), null, false, undefined);
    assert.equal(ignored.children.length, 1, 'null/false children are skipped as before');
  } finally {
    delete globalThis.Node;
    delete globalThis.document;
  }
});

test('the history canvas draws through Path2D, not through a path string fill rule', () => {
  assert.match(historySource, /new Path2D\(path\)/, 'drawFeature must build a Path2D');
  assert.doesNotMatch(historySource, /context\.fill\(\s*path\s*\)/, 'a path string is not a fill rule');
  assert.doesNotMatch(historySource, /context\.stroke\(\s*path\s*\)/, 'a path string is not a stroke path');
});

test('the history module keeps the world-wide defaults and the named-snapshot copy', () => {
  assert.match(historySource, /Snapshot \$\{formatYear\(near\.year\)\}/, 'the represented snapshot is always named');
  assert.match(historySource, /nearest published map/, 'an in-between year says it substitutes a snapshot');
  assert.match(historySource, /app-history-link/, 'the archive landing page gets an entry point');
  assert.match(historySource, /\.zh-header__meta/, 'the mode switch lives in the header, not above the map');
});

